import sys

class Character:
    def attack(self):
        pass

    def __del__(self):
        pass

class Warrior(Character):
    def attack(self):
        print("Warrior slashes with Sword!")

    def __del__(self):
        pass

class Mage(Character):
    def attack(self):
        print("Mage casts Fireball!")

    def __del__(self):
        pass

class Archer(Character):
    def attack(self):
        print("Archer shoots an Arrow!")

    def __del__(self):
        pass

def main():
    char_type = sys.stdin.readline().strip()

    characters = {
        'Warrior': Warrior(),
        'Mage': Mage(),
        'Archer': Archer()
    }

    if char_type in characters:
        characters[char_type].attack()

if __name__ == "__main__":
    main()
